INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10686, 276908, 'tt2965412', NULL, 'Comet', 'Comet', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/4zOOSa5zyJDvqDDKFwUQVMK6eDe.jpg', 'https://image.tmdb.org/t/p/original/znDbUAz0uPgc329iHBiobnnYA2P.jpg', 'When a chance encounter brings together the cynical Dell and the quick-witted Kimberly, the stage is set for a tempestuous love affair that unfolds like a puzzle. As the film zigzags back and forth in time — from a meteor shower in LA, to an encounter in a Paris hotel room, to a fateful phone call — an unforgettable portrait of a relationship emerges.', NULL, NULL, 1.316, 6.626, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10687, 18252, 'tt0089652', NULL, 'My Science Project', 'My Science Project', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/1fbVPx5VVEsgJ7M9sTzvbDjhgks.jpg', 'https://image.tmdb.org/t/p/original/2KDfY3QCRz23Xdi21Ey6ATa7Oe8.jpg', 'His high school teacher issues an ultimatum: turn in a science project or flunk. So Mike Harlan scavenges a military base''s junk pile for a suitable gizmo. He finds one... and unwittingly unleashes the awesome power and energy of the unknown. Twisted dimensions. Time warps. A fantastic realm where the past, present, and future collide in a whirling vortex of startling adventure and superlative special effects.', NULL, NULL, 2.0443, 6.268, 0, 5.785, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10688, 40344, 'tt0134304', NULL, 'Balloon Farm', 'Balloon Farm', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/6CxEDv29kHEGRFxXl1nQVFBQ1ea.jpg', 'https://image.tmdb.org/t/p/original/pC7cfWA7vHjgxe8UX7bsLAYdv66.jpg', 'As soon as Harvey S. Potter descends upon a drought-stricken farmland, he begins to grow a mysterious but beautiful crop of balloons. Mystified by the new resident''s abilities, the people of the town are mesmerized by Potter, who immediately becomes the best thing to happen to the dejected area in a long time. The happiness doesn''t last long, however, when talk begins to surface about Potter''s true identity.', NULL, NULL, 1.1131, 5.9, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10689, 24086, 'tt0090768', NULL, 'The Boy Who Could Fly', 'The Boy Who Could Fly', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/gPNKA4uL39DrzngMRMx3EULPmvq.jpg', 'https://image.tmdb.org/t/p/original/fJl4hxSlAtTyfbzw7XZE6OMbGYi.jpg', 'Milly and Louis, and their recently-widowed mom, Charlene, move to a new neighborhood. Once there, they all deal with a variety of personal problems, but Milly finds a friend in Eric, her autistic next door neighbor. Eric has a fascination with flight, and as the story progresses, he exerts an enthralling force of change on all those around him.', NULL, NULL, 16.7927, 6.3, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10690, 1165452, 'tt17423262', NULL, 'The Last Video Store', 'The Last Video Store', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/3BXinffNu2OLFg41f2A4uD8VHk2.jpg', 'https://image.tmdb.org/t/p/original/5oVh39vTFG34ESf2XDSiPnDlHtA.jpg', 'A young woman who is unknowingly in possession of a legendary "cursed tape" takes a collection of old video tapes to a video store. She and the store owner re-awake its curse, which leads to the release of a raft of cinematic villains.', NULL, NULL, 0.4543, 5.1, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10691, 607430, 'tt10451852', NULL, 'Nine Days', 'Nine Days', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/6ZemGof32GQRpAMfIK9Q2VFJdwt.jpg', 'https://image.tmdb.org/t/p/original/wLewdoshX7fqzsDoMlTP5njnckP.jpg', 'A bureaucrat interviews five souls to decide which of them will be given a life on Earth. But he soon faces an existential challenge of his own.', NULL, NULL, 1.5895, 6.829, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10692, 82690, 'tt1772341', NULL, 'Wreck-It Ralph', 'Wreck-It Ralph', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/nrEupcBwf4O1zihCM34NoXusZDq.jpg', 'https://image.tmdb.org/t/p/original/3IFRjBDwtk0DlIsDfJ2zEzLjUBi.jpg', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', NULL, NULL, 16.5804, 7.361, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10693, 10796, 'tt0267804', NULL, 'The One', 'The One', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/gcr3t71KmeXINemMrhaGBGVJPwW.jpg', 'https://image.tmdb.org/t/p/original/yZzPTih3HQZUBghrWirt0Rk17uE.jpg', 'A sheriff''s deputy fights an alternate universe version of himself who grows stronger with each alternate self he kills.', NULL, NULL, 6.2595, 6.132, 0, 8.06, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10694, 205504, 'tt26748360', NULL, 'Royal Crackers', 'Royal Crackers', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/cWcOkakVjLxqALDCYOt0fjjrNzw.jpg', 'https://image.tmdb.org/t/p/original/i6wdNXc1qCFIn8JxwrRWtak5ykP.jpg', 'Royal Crackers was once the king of snacks, but the empire is crumbling. When the family patriarch, tyrannical company founder Theodore Hornsby Sr. ends up in a “super coma,” the rest of the Hornsbys will take their lack of talent and business acumen and try to make Royal Crackers the success it once was.', NULL, NULL, 9.2864, 5.846, 0, 6.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10695, 11535, 'tt0246894', NULL, 'Rollerball', 'Rollerball', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/5Wquo3EjfDpK7S1BHcybuC3TZDO.jpg', 'https://image.tmdb.org/t/p/original/tjCAyz2Tu2xdZSFJrtU4fQrZ32A.jpg', 'In this fast action-packed thriller, Jonathan, Marcus, and Aurora compete in a dangerous, fierce sport called Rollerball. Although, Johnathan and Marcus try to quit, cruel and vindictive promoter Alexi Petrovich encourages them to still participate.', NULL, NULL, 2.2112, 3.89, 0, 7.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10696, 27791, 'tt0124102', NULL, 'Strangeland', 'Strangeland', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/AhQh5rtPymR1J8daZc0FNXiSkU.jpg', 'https://image.tmdb.org/t/p/original/7F59vpblBh2q62rdhdrObP7mJ6q.jpg', 'A pierced and tattooed sadist, Captain Howdy, trolls the Internet for naive teens, luring them to his home to torture and defile them. When Howdy kidnaps and tortures the daughter of police Detective Mike Gage, he is caught. Deemed insane, he is sent to an asylum but is released soon after, seemingly better. However, Gage knows it is only a matter of time before Howdy strikes again, and he''s ready to unleash his own form of retribution when the time comes.', NULL, NULL, 1.2144, 5.051, 0, 1.12, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10697, 238636, 'tt2975578', NULL, 'The Purge: Anarchy', 'The Purge: Anarchy', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/qwqHHZLZSUvMkAMQ47ymtfjEifY.jpg', 'https://image.tmdb.org/t/p/original/blfZnm6StMPnTY35kaooPBCsSVp.jpg', 'One night per year, the government sanctions a 12-hour period in which citizens can commit any crime they wish -- including murder -- without fear of punishment or imprisonment. Leo, a sergeant who lost his son, plans a vigilante mission of revenge during the mayhem. However, instead of a death-dealing avenger, he becomes the unexpected protector of four innocent strangers who desperately need his help if they are to survive the night.', NULL, NULL, 12.2699, 6.617, 0, 1.03, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10698, 10992, 'tt0239395', NULL, 'Cats & Dogs', 'Cats & Dogs', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/wUWoat7L4vvQburQ8pVEJhRG9L5.jpg', 'https://image.tmdb.org/t/p/original/3ipuPBeBfsxcsry7Gh5m9J1rwJ1.jpg', 'When a professor develops a vaccine that eliminates human allergies to dogs, he unwittingly upsets the fragile balance of power between cats and dogs and touches off an epic battle for pet supremacy. The fur flies as the feline faction, led by Mr. Tinkles, squares off against wide-eyed puppy Lou and his canine cohorts.', NULL, NULL, 4.4925, 5.399, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10699, 32307, 'tt0058548', NULL, 'Santa Claus Conquers the Martians', 'Santa Claus Conquers the Martians', 'movie', 1964, 'https://image.tmdb.org/t/p/w500/f8lxrcMx98AuvlLSb2hPkz0CuH0.jpg', 'https://image.tmdb.org/t/p/original/5f1Li4gdAa16VEwTePZIQ29kPrg.jpg', 'Martians fear their children have become lazy and joyless due to their newfound obsession with Earth TV shows. After ancient Martian leader Chochem suggests that the children of Mars need more fun—including their own Santa Claus—supreme leader Lord Kimar assembles an expedition to Earth. Once there, they kidnap two children who lead them to the North Pole, then capture the real Santa Claus, taking all three back to Mars in an attempt to bring the Martian children happiness.', NULL, NULL, 0.9468, 3.132, 0, 1.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10700, 20521, 'tt0404364', NULL, 'Reefer Madness: The Movie Musical', 'Reefer Madness: The Movie Musical', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/38xnsPZiuIYMTsOXhtTIg1dUnRu.jpg', 'https://image.tmdb.org/t/p/original/Ag660gnSIe3UpL2s7gAqj8OeYs7.jpg', 'From an ominous Lecturer, a small 1930s middle American community learns of the Harper Affair, in which young Jimmy Harper finds his life of promise turn into a life of debauchery and murder thanks to the new drug menace marijuana. Along the way, he receives help from his girlfriend Mary and Jesus Himself, but always finds himself in the arms of the Reefer Man and the rest of the denizens of the Reefer Den.', NULL, NULL, 2.1189, 6.6, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
