INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10759, 7737, 'tt0432021', NULL, 'Resident Evil: Extinction', 'Resident Evil: Extinction', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/6yaLr7Ymg5cvbtSVi5hHwBKx35I.jpg', 'https://image.tmdb.org/t/p/original/u8QUvrq24pWB2x1DxCy4ulbKJG5.jpg', 'Years after the Racoon City catastrophe, survivors travel across the Nevada desert, hoping to make it to Alaska. Alice joins the caravan and their fight against hordes of zombies and the evil Umbrella Corp.', NULL, NULL, 2.3368, 6.3, 0, 2.025, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10760, NULL, NULL, 16, 'Fallout: New Vegas', 'Fallout: New Vegas', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u60.jpg', NULL, 'In this first-person Western RPG, the player takes on the role of Courier 6, barely surviving after being robbed of their cargo, shot and put into a shallow grave by a New Vegas mob boss. The Courier sets out to track down their robbers and retrieve their cargo, and winds up getting tangled in the complex ideological and socioeconomic web of the many factions and settlements of post-nuclear Nevada.', 'https://www.igdb.com/games/fallout-new-vegas', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, NULL, 0, 1.0, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10761, 13908, 'tt0295427', NULL, 'The Master of Disguise', 'The Master of Disguise', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/JFKuKJeHHFFVb0ubpkPIXmkIOg.jpg', 'https://image.tmdb.org/t/p/original/fRATaeFqwsaHJuC7ERsGzoYs2lU.jpg', 'After the patriarch of the Disguisey family is kidnapped by Devlin Bowman in an attempt to steal the most precious treasures from around the world, Italian waiter Pistachio Disguisey utilizes his supernatural ability to disguise himself in an attempt to stop him.', NULL, NULL, 2.3948, 4.001, 0, 9.65, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10762, 62016, 'tt0339593', NULL, 'Rolie Polie Olie: The Great Defender of Fun', 'Rolie Polie Olie: The Great Defender of Fun', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/cz9d0nl67VnSAxOY3IhufkxidrU.jpg', 'https://image.tmdb.org/t/p/original/94tXQ7iD84Fj1yNdKut6G9dPRyL.jpg', 'The evil space pirate Gloomius Maximus is determined that since he can''t have fun, nobody else will either. Unfortunately for our heroes, an invitation to Zowie Polie''s third birthday party accidentally finds its way to Gloomius''s ship. Gloomius never had a birthday party himself, so he sets out to make Zowie''s as miserable as possible. He tries a glum ray, kidnapping Zowie and Pappy, and ultimately towing the entire Polie Planet to the Gloomy Galaxy. Between Olie''s Super Silly Ray (his present to Zowie) and some help from Saturday morning hero Space Boy the day is saved for silliness. The whole planet helps charge up the Super Silly Ray and fix Gloomius''s happy gear.', NULL, NULL, 1.0171, 6.3, 0, 9.06, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10763, 14759, 'tt0877512', NULL, 'Yo Gabba Gabba!', 'Yo Gabba Gabba!', 'tv', 2007, 'https://image.tmdb.org/t/p/w500/h8UHNBBnJwdXVtMIA5OAxJoXWid.jpg', 'https://image.tmdb.org/t/p/original/5heUHCpib5gGY8WvWatJvQ1Ba0t.jpg', 'Yo Gabba Gabba! is an American children''s television show that airs on the Nick Jr. cable network in the United States and the Nick Jr. networks in the United Kingdom & Ireland, Italy, France and Australia as well as Treehouse TV network in Canada and RTE2 on RTÉjr in Ireland.  The show stars five costumed toys-come-to-life and their friend DJ Lance Rock, who explore a single topic in each episode through songs and short storylines in the half-hour program while teaching children life and social skills.  It also encourages viewers to move along with and dance with the characters in the program. The show is noted for its indie-culture guest stars and bands, and for drawing visual inspiration from 8-bit video games and H. R. Pufnstuff.', NULL, NULL, 9.5932, 7.1, 0, 9.52, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10764, 7430, 'tt2228547', NULL, 'The Aquabats! Super Show!', 'The Aquabats! Super Show!', 'tv', 2012, 'https://image.tmdb.org/t/p/w500/dTlEWqy0xjlvX6CSedrIlZ23Djx.jpg', 'https://image.tmdb.org/t/p/original/oaZGWAj5ZDT6DDjknDXjNfHjI4l.jpg', 'The Aquabats! Super Show! is an American action-comedy television series which premiered on March 3, 2012 on the United States cable network The Hub. The series was created by Christian Jacobs and Scott Schultz, both the creators of the Nick Jr. series Yo Gabba Gabba!, and Jason deVilliers.

Based on the superhero mythology of The Aquabats, a real-life comedy rock band which series co-creator and lead singer Jacobs formed in 1994, The Aquabats! Super Show! follows the comic adventures of a fictionalized version of the band, a musical group of amateur superheroes, as they haphazardly defend the world from a variety of villains and monsters. Styled similarly to the campy aesthetics of 1960s and 1970s children''s television and Japanese tokusatsu, Super Show! utilizes various mediums of visual styles and special effects, mixing live-action storylines with cartoon shorts, parody advertisements and musical interludes.', NULL, NULL, 2.823, 7.5, 0, 9.52, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10765, 19018, 'tt0472221', NULL, 'Care Bears: Big Wish Movie', 'Care Bears: Big Wish Movie', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/aolQObgjpu9QRShA1s6V1zJcaCc.jpg', NULL, 'Feeling sad that her fellow Care Bears don''t seem to appreciate her wishes, Wish Bear uses her wish star, Twinkers, to find some bears who love wishing as much as she does. That''s when three new bears move to Care-a-lot...with some very unexpected results.', NULL, NULL, 0.7907, 7.2, 0, 9.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10766, 11867, 'tt0115624', NULL, 'Barb Wire', 'Barb Wire', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/eACq1joafhQTD12gGXNS13J06B.jpg', 'https://image.tmdb.org/t/p/original/o7bxmFoHfEP5JiBzVYY5QgLiSfU.jpg', 'A sexy nightclub owner, Barb Wire moonlights as a mercenary in Steel Harbor, one of the last free zones in the now fascist United States. When scientist Cora Devonshire wanders into Barb''s establishment, she gets roped into a top-secret government plot involving biological weapons. Soon Barb is reunited with her old flame Axel Hood, who is now Cora''s husband and a guerrilla fighter, resulting in plenty of tense action.', NULL, NULL, 3.9471, 4.122, 0, 8.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
