INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10768, 121, 'tt0056751', NULL, 'Doctor Who', 'Doctor Who', 'tv', 1963, 'https://image.tmdb.org/t/p/w500/xinqAmYrZ1TEwowcQhgTkZVtVE0.jpg', 'https://image.tmdb.org/t/p/original/8VWgyQjExeMgeg6Qzv6agduMU1A.jpg', 'The adventures of The Doctor, a time-traveling humanoid alien known as a Time Lord. He explores the universe in his TARDIS, a sentient time-traveling spaceship. Its exterior appears as a blue British police box, which was a common sight in Britain in 1963 when the series first aired. Along with a succession of companions, The Doctor faces a variety of foes while working to save civilizations, help ordinary people, and right many wrongs.', NULL, NULL, 52.2742, 7.916, 0, 7.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10769, 22907, 'tt1135084', NULL, 'Takers', 'Takers', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/s2zx7JA87rkQcmsV40k0vbVJ6oh.jpg', 'https://image.tmdb.org/t/p/original/2MmcWazB76kabQ1livKMqIUfN80.jpg', 'A seasoned team of bank robbers, including Gordon Jennings, John Rahway, A.J., and brothers Jake and Jesse Attica successfully complete their latest heist and lead a life of luxury while planning their next job. When Ghost, a former member of their team, is released from prison he convinces the group to strike an armored car carrying $20 million. As the "Takers" carefully plot out their strategy and draw nearer to exacting the grand heist, a reckless police officer inches closer to apprehending the criminals.', NULL, NULL, 4.0587, 6.3, 0, 1.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10770, 324542, 'tt2072233', NULL, 'Sleepless', 'Sleepless', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/9WkUSY33MDPGmz0vtzbsfaxTHVa.jpg', 'https://image.tmdb.org/t/p/original/9VEOQvCnd8T8wILgyqjKgyhALw4.jpg', 'Undercover Las Vegas police officer Vincent Downs, who has a lot of enemies, is caught in a high stakes web of corrupt cops and the mob-controlled casino underground. When a heist goes wrong, a crew of homicidal gangsters kidnap Downs’ teenage son T. In one sleepless night, Downs will have to rescue his son, evade an internal affairs investigation, and bring the kidnappers to justice.', NULL, NULL, 3.0731, 5.925, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
