INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10774, 25117, 'tt0152183', NULL, 'Bill Hicks: Revelations', 'Bill Hicks: Revelations', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/1xcuMgFbvWZBoTKS46Xbo5kOMj.jpg', 'https://image.tmdb.org/t/p/original/w146wheGBiKdMpajOVNV7A8YALE.jpg', 'Bill Hicks in the height of his genius. Recorded at the Dominion Theatre in London, Hicks opens our eyes and minds to the hypocrisy and ludicrousness of the world around us.', NULL, NULL, 0.4836, 7.959, 0, 9.03, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10775, NULL, NULL, 17000, 'Stardew Valley', 'Stardew Valley', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa93h.jpg', NULL, 'Stardew Valley is an open-ended country-life RPG! You’ve inherited your grandfather’s old farm plot in Stardew Valley. Armed with hand-me-down tools and a few coins, you set out to begin your new life. Can you learn to live off the land and turn these overgrown fields into a thriving home? It won’t be easy. Ever since Joja Corporation came to town, the old ways of life have all but disappeared. The community center, once the town’s most vibrant hub of activity, now lies in shambles. But the valley seems full of opportunity. With a little dedication, you might just be the one to restore Stardew Valley to greatness!', 'https://www.igdb.com/games/stardew-valley', '["PlayStation 4", "Linux", "Nintendo Switch 2", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Wii U", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 9.03, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10776, NULL, NULL, 119388, 'The Legend of Zelda: Tears of the Kingdom', 'The Legend of Zelda: Tears of the Kingdom', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vmg.jpg', NULL, 'An epic adventure across the land and skies of Hyrule awaits in The Legend of Zelda: Tears of the Kingdom for Nintendo Switch. The adventure is yours to create in a world fueled by your imagination.

In this sequel to The Legend of Zelda: Breath of the Wild, you''ll decide your own path through the sprawling landscapes of Hyrule and the mysterious islands floating in the vast skies above. Can you harness the power of Link''s new abilities to fight back against the malevolent forces that threaten the kingdom?', 'https://www.igdb.com/games/the-legend-of-zelda-tears-of-the-kingdom', '["Nintendo Switch"]', NULL, NULL, 0, 8.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10777, 205618, 'tt0192792', NULL, 'The White Pony', 'The White Pony', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/y72ADEZ9ELz7hMtaCPDCIQvA6fV.jpg', 'https://image.tmdb.org/t/p/original/5GDhrLAzoOVnELnLG6Ya6IqLxL5.jpg', 'Leah is eager to visit her uncle''s ranch in Ireland, until her attempt to ride her cold cousin Shannon''s horse results in Silky being injured and she is ordered not to ride again. When she meets Lucky, a leprechaun who only communicates with her, she learns that the beautiful white beast she''s glimpsed from afar is in fact a bewitched fairy Sorica, who needs help retrieving a magical horn to return to her true form and her own world. Now Leah must juggle secretly helping Lucky, whose reasons for helping might not just be out of kindness; putting up with Shannon; and trying to win Uncle Jaques'' trust by entering her newfound "horse" in the local race.', NULL, NULL, 0.6037, 5.833, 0, 7.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10778, 444090, 'tt5628418', NULL, 'The Ash Lad: In the Hall of the Mountain King', 'Askeladden - I Dovregubbens hall', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/uyJEfpAflLCkqn6PFHu9EHxmbI6.jpg', 'https://image.tmdb.org/t/p/original/iFMARpEJnSQBUDKzKvvRw6ATVF3.jpg', 'Espen “Ash Lad”, a poor farmer’s son, embarks on a dangerous quest with his brothers to save the princess from a vile troll known as the Mountain King – in order to collect a reward and save his family’s farm from ruin.', NULL, NULL, 3.0893, 6.794, 0, 7.51, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
