INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10784, 465550, 'tt3531176', NULL, 'Big Sonia', 'Big Sonia', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/gluvPoUpEQ55x8jerhzx2d6HsZr.jpg', 'https://image.tmdb.org/t/p/original/1TQ5Q7HmWSKdnJFBdk4zTaTko93.jpg', 'In the last store in a defunct shopping mall, 91-year-old Sonia Warshawski – great-grandmother, businesswoman, and Holocaust survivor – runs the tailor shop she’s owned for more than 30 years. But when she’s served an eviction notice, the specter of retirement prompts Sonia to resist her harrowing past as a refugee and witness to genocide.', NULL, NULL, 0.3236, 8.5, 0, 1.01, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
