INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10808, 21845, 'tt0107985', NULL, 'Rookie of the Year', 'Rookie of the Year', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/9If8XnhBdEbQ2Q0ggAQC92CptjU.jpg', 'https://image.tmdb.org/t/p/original/AsiZIxTfcSSj2Ti9s88F17pzjrF.jpg', '12-year-old Henry Rowengartner, whose late father was a minor league baseball player, grew up dreaming of playing baseball, despite his physical shortcomings. After Henry''s arm is broken while trying to catch a baseball at school, the tendon in that arm heals too tightly, allowing Henry to throw pitches that are as fast as 103 mph. Henry is spotted at nearby Wrigley Field by Larry "Fish" Fisher, the general manager of the struggling Chicago Cubs, after Henry throws an opponent''s home-run ball all the way from the outfield bleachers back to the catcher, and it seems that Henry may be the pitcher that team owner Bob Carson has been praying for.', NULL, NULL, 5.0476, 6.17, 0, 1.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
