INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10831, 9692, 'tt0361127', NULL, 'The Woodsman', 'The Woodsman', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/4fDgLcc35A0IpxhMyJMP33bSDXj.jpg', 'https://image.tmdb.org/t/p/original/ebojikILvOdZlVMWmp9WJLv1LVh.jpg', 'After twelve years in prison, Walter returns home. His family has abandoned him, save for his brother-in-law. Few know he''s a sex offender and pedophile. Walter finds an apartment and is regularly visited by his parole officer. He gets a job at a lumber mill and starts seeing a coworker. Then his new world begins to unravel; as his past becomes known, he strikes up a high-risk friendship with a young girl and realizes that a man loitering near a schoolyard is a child molester prowling for his next victim.', NULL, NULL, 1.8722, 6.84, 0, 8.56, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
