INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10842, 5261, 'tt0207198', NULL, 'What to Do in Case of Fire?', 'Was tun, wenn''s brennt?', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/z6PHgCsUpcK2n7m577fSJdoIy7k.jpg', 'https://image.tmdb.org/t/p/original/whKiywHUvnuzJkGQDG0KlKE8mad.jpg', 'The humorous and touching story of six former creative anarchists who lived as house squatters in Berlin during its heyday in the 80s when Berlin was still an island in the middle of the former East Germany. At the end of the 80s, they went their separate ways with the exception of Tim and Hotte, who have remained true to their ideals and continue to fight the issues they did as a group. In 2000, with Berlin as Germany''s new capital, an event happens forcing the group out of existential reason to reunite and, ultimately, come to terms with the reason they separated 12 years ago.', NULL, NULL, 1.3218, 6.27, 0, 1.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
