INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10846, 28766, 'tt0159693', NULL, 'Razor Blade Smile', 'Razor Blade Smile', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/sMVuGc7VU9Sp4SLz544QhjtWtjK.jpg', 'https://image.tmdb.org/t/p/original/hhVpNrUGfM7pYOMWTu5NmS2SdFC.jpg', 'A 19th century woman, who has become one of the undead, acts as a hired killer in modern times. When she starts knocking off part of the elite businessmen, "The Illuminati", who secretly are taking over business and the government, she becomes the target of a hired Scotland Yard detective. Of course, the head of "The Illuminati" is the vampire who first gave her immortality.', NULL, NULL, 0.8739, 4.185, 0, 11.03, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
