INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10848, 18979, 'tt0071276', NULL, 'Captain Kronos: Vampire Hunter', 'Captain Kronos: Vampire Hunter', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/4i6vRcVl9sE3W7ouQ8KC2B5NiJD.jpg', 'https://image.tmdb.org/t/p/original/37O5VkS3AHJpbMh4dzovjGUWXzl.jpg', 'When several young girls are found dead, left hideously aged and void of blood, Dr. Marcus suspects vampirism. He enlists the help of the Vampire Hunter. Mysterious and powerful, Kronos has dedicated his life to destroying the evil pestilence. Once a victim of its diabolical depravity, he knows the vampire''s strengths and weaknesses as well as the extreme dangers attached to confronting the potent forces of darkness.', NULL, NULL, 1.0716, 6.1, 0, 11.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
