INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10918, 837214, 'tt13694438', NULL, 'Scenes from an Empty Church', 'Scenes from an Empty Church', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/ubIly1wzLZSo774wGYAsjZoi9vA.jpg', NULL, 'In a locked-down NYC, two priests open their church doors to those seeking salvation during the most isolating of times. From the commonplace to the truly metaphysical, their visitors reflect the full spectrum of personal crises of spirituality. Throughout their encounters with the city''s sweetest, wildest and weirdest, the two priests learn the importance of connection, empathy and open-mindedness. Sometimes a little faith is all you need to make it through the bad times.', NULL, NULL, 0.4123, 3.0, 0, 9.02, '2026-08-20 01:43:50', '2026-08-20 01:43:50');
