UPDATE "recommendations" SET "tmdb_id"=9886, "imdb_id"='tt0113481', "igdb_id"=NULL, "title"='Johnny Mnemonic', "original_title"='Johnny Mnemonic', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/iH8Jgi8qvb7pnBfI8fVGaUbyRna.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7FRYVIF2hnh1IbPtqMgF5iygdjz.jpg', "overview"='In a dystopian 2021, Johnny is a data trafficker who has an implant that allows him to securely store data too sensitive for regular computer networks. On one delivery run, he accepts a package that not only exceeds the implant''s safety limits—and will kill him if the data is not removed in time—but also contains information far more important and valuable than he had ever imagined. On a race against time, he must avoid the assassins sent to kill him and remove the data before it, too, ends his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3516, "vote_average"=5.758, "is_ambiguous"=0, "evidence_score"=2.56204347826086973e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=785;
UPDATE "recommendations" SET "tmdb_id"=82507, "imdb_id"='tt1922777', "igdb_id"=NULL, "title"='Sinister', "original_title"='Sinister', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nzx10sca3arCeYBAomHan4Q6wa1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jovIEk4cAxWmA2dBcPrfhn3jzYN.jpg', "overview"='True-crime writer Ellison Oswalt is in a slump; he hasn''t had a best seller in more than 10 years and is becoming increasingly desperate for a hit. So, when he discovers the existence of a snuff film showing the deaths of a family, he vows to solve the mystery. He moves his own family into the victims'' home and gets to work. However, when old film footage and other clues hint at the presence of a supernatural force, Ellison learns that living in the house may be fatal.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.8983, "vote_average"=6.876, "is_ambiguous"=0, "evidence_score"=3.25346666666666664e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=791;
UPDATE "recommendations" SET "tmdb_id"=9479, "imdb_id"='tt0107688', "igdb_id"=NULL, "title"='The Nightmare Before Christmas', "original_title"='The Nightmare Before Christmas', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', "overview"='Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', "external_url"=NULL, "platforms"=NULL, "popularity"=13.3684, "vote_average"=7.834, "is_ambiguous"=0, "evidence_score"=16.36, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=801;
UPDATE "recommendations" SET "tmdb_id"=411, "imdb_id"='tt0363771', "igdb_id"=NULL, "title"='The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', "original_title"='The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/iREd0rNCjYdf5Ar0vfaW32yrkm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tuDhEdza074bA497bO9WFEPs6O6.jpg', "overview"='Siblings Lucy, Edmund, Susan and Peter step through a magical wardrobe and find the land of Narnia. There, they discover a charming, once peaceful kingdom that has been plunged into eternal winter by the evil White Witch, Jadis. Aided by the wise and magnificent lion, Aslan, the children lead Narnia into a spectacular, climactic battle to be free of the Witch''s glacial powers forever.', "external_url"=NULL, "platforms"=NULL, "popularity"=21.5964, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=2.78154166666666675e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=807;
UPDATE "recommendations" SET "tmdb_id"=22538, "imdb_id"='tt0446029', "igdb_id"=NULL, "title"='Scott Pilgrim vs. the World', "original_title"='Scott Pilgrim vs. the World', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/g5IoYeudx9XBEfwNL0fHvSckLBz.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6R9nT6m8wmzayV5XOQq3TRA6yZw.jpg', "overview"='As bass guitarist for a garage-rock band, Scott Pilgrim has never had trouble getting a girlfriend; usually, the problem is getting rid of them. But when Ramona Flowers skates into his heart, he finds she has the most troublesome baggage of all: an army of ex-boyfriends who will stop at nothing to eliminate him from her list of suitors.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.4636, "vote_average"=7.486, "is_ambiguous"=0, "evidence_score"=43.55525, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=808;
