UPDATE "recommendations" SET "tmdb_id"=616825, "imdb_id"='tt10332416', "igdb_id"=NULL, "title"='Oil Capital Underground: The Genesis & Evolution of Punk Rock in Tulsa-Late 70''s to Mid 90''s', "original_title"='Oil Capital Underground: The Genesis & Evolution of Punk Rock in Tulsa-Late 70''s to Mid 90''s', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/yGH9eKJkpsJuzPgjQSksd0dH5WT.jpg', "backdrop_url"=NULL, "overview"='A documentary about the underground punk/new wave/thrash scene in Tulsa Oklahoma, focusing on the late 70s up until the mid 90s. Going against the grain in the conservative atmosphere of the city formerly known as the Oil Capital of the World, bands such as Los Reactors, NOTA, Pitbulls On Crack, Bunnies of Doom, Baby M, Brother Inferior, Tex Montana''s Green Party and many others struggled to make a name for themselves releasing their own music and playing local and national venues. Oil Capital Underground is filled with rare live footage, flyers, photos and interviews with many of the colorful musicians, promoters and club owners discussing the music, personalities and social climate of the time.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.2242, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=1.76911111111111125e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=1313;
