UPDATE "recommendations" SET "tmdb_id"=11649, "imdb_id"='tt0093507', "igdb_id"=NULL, "title"='Masters of the Universe', "original_title"='Masters of the Universe', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/gaUecXFd31V68yOTJPJYaB9YhAf.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/v2IoEKNJIvBneE6qBgntY0nlmhM.jpg', "overview"='When the evil Skeletor finds a mysterious power called the Cosmic Key, he becomes nearly invincible, seizing Castle Grayskull and the surrounding city. The Sorceress is now Skeletor''s prisoner and he begins to drain her life-force as he waits for the moon of Eternia to align with the Great Eye of the Universe which will bestow god-like power upon him. However, courageous warrior He-Man locates the locksmith inventor Gwildor, who created the Key and has another version of it. During a battle, one of the Keys is transported to Earth, where it is found by teenagers Julie and Kevin. Now, both He-Man and Skeletor''s forces arrive on Earth searching for the potent weapon.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.8885, "vote_average"=5.903, "is_ambiguous"=0, "evidence_score"=10.02, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=1411;
