UPDATE "recommendations" SET "tmdb_id"=13446, "imdb_id"='tt0094336', "igdb_id"=NULL, "title"='Withnail & I', "original_title"='Withnail & I', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/i18cIp8A10A2JgByrfA9oIC9299.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bOgKCymrdPHPHozhRBNr9XhVD87.jpg', "overview"='Two out-of-work actors -- the anxious, luckless Marwood and his acerbic, alcoholic friend, Withnail -- spend their days drifting between their squalid flat, the unemployment office and the pub. When they take a holiday "by mistake" at the country house of Withnail''s flamboyantly gay uncle, Monty, they encounter the unpleasant side of the English countryside: tedium, terrifying locals and torrential rain.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.4476, "vote_average"=7.226, "is_ambiguous"=0, "evidence_score"=1.88474999999999965e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=2116;
