UPDATE "recommendations" SET "tmdb_id"=30923, "imdb_id"='tt0164993', "igdb_id"=NULL, "title"='Alice in Wonderland', "original_title"='Alice in Wonderland', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/kpXmXjqeyuSYCtNuGMytWQLdKX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mbFHUlhWU53VG8VLE5jAcQQVIUR.jpg', "overview"='Alice follows a white rabbit down a rabbit-hole into a whimsical Wonderland, where she meets characters like the delightful Cheshire Cat, the clumsy White Knight, a rude caterpillar, and the hot-tempered Queen of Hearts and can grow ten feet tall or shrink to three inches. But will she ever be able to return home?', "external_url"=NULL, "platforms"=NULL, "popularity"=3.0786, "vote_average"=6.226, "is_ambiguous"=0, "evidence_score"=1.26057142857142849e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=2122;
UPDATE "recommendations" SET "tmdb_id"=36819, "imdb_id"='tt0081633', "igdb_id"=NULL, "title"='Time Bandits', "original_title"='Time Bandits', "media_type"='movie', "release_year"=1981, "poster_url"='https://image.tmdb.org/t/p/w500/4VZtpwdhHQSa4LUkvujyGAHb1hG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qKERrt3UU1ml8Q9zdsLPpoQ5r3.jpg', "overview"='Young history buff Kevin can scarcely believe it when six dwarfs emerge from his closet one night. Former employees of the Supreme Being, they''ve purloined a map charting all of the holes in the fabric of time and are using it to steal treasures from different historical eras. Taking Kevin with them, they variously drop in on Napoleon, Robin Hood and King Agamemnon before the Supreme Being catches up with them.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.5354, "vote_average"=6.626, "is_ambiguous"=0, "evidence_score"=2.44721052631578928e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-20 01:43:50' WHERE "id"=2131;
