UPDATE "recommendations" SET "tmdb_id"=14361, "imdb_id"='tt0103924', "igdb_id"=NULL, "title"='Captain Ron', "original_title"='Captain Ron', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/otnKFXvqFH2swlrNf2sNiXpnIsR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cUqa9ngoI72dFGVQKVLsTbzj65B.jpg', "overview"='When mild-mannered Martin Harvey finds out that he has inherited a vintage yacht, he decides to take his family on a Caribbean vacation to retrieve the vessel. Upon arriving on a small island and realizing that the ship is in rough shape, Martin and his family end up with more than they bargained for as the roguish Captain Ron signs on to sail the boat to Miami. It doesn''t take long before Ron''s anything-goes antics get the Harveys into plenty of trouble.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5511, "vote_average"=5.593, "is_ambiguous"=0, "evidence_score"=1.66181818181818172e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-20 01:43:50' WHERE "id"=3458;
UPDATE "recommendations" SET "tmdb_id"=8676, "imdb_id"='tt0770752', "igdb_id"=NULL, "title"='Fool''s Gold', "original_title"='Fool''s Gold', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/f4djEBW3nyGRPLTcDlWYyaO43mx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6vsZR4066s6ZbaAAqDdzDbC4kgH.jpg', "overview"='Treasure hunter Ben "Finn" Finnegan has sunk his marriage to Tess and his trusty boat in his obsessive quest to find the legendary Queen''s Dowry. When he finds a vital clue that may finally pinpoint the treasure''s whereabouts, he drags Tess and her boss, billionaire Nigel Honeycutt, along on the hunt. But Finn is not the only one interested in the gold; his former mentor-turned-enemy Moe Fitch, hired by rapper-turned-gangster Bigg Bunny, will stop at nothing to beat him to it.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.7878, "vote_average"=5.792, "is_ambiguous"=0, "evidence_score"=8.00333333333333385e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-20 01:43:50' WHERE "id"=3460;
UPDATE "recommendations" SET "tmdb_id"=9870, "imdb_id"='tt0800039', "igdb_id"=NULL, "title"='Forgetting Sarah Marshall', "original_title"='Forgetting Sarah Marshall', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/d4elOzyhNWVlxpG7BwigrumkFTe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/s39aQY3dK1s6ARrUKP5yeq824nR.jpg', "overview"='When actress Sarah Marshall dumps aspiring musician Peter Bretter for rock star Aldous Snow, Peter''s world comes crashing down. His best friend Brian suggests that Peter should get away from everything and to fly off to Hawaii to escape all his problems. After arriving in Hawaii and meeting the beautiful receptionist Rachel Jansen, Peter is shocked to see not only Aldous in Hawaii, but also Sarah.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0411, "vote_average"=6.507, "is_ambiguous"=0, "evidence_score"=1.72957142857142862e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-20 01:43:50' WHERE "id"=3462;
UPDATE "recommendations" SET "tmdb_id"=1824, "imdb_id"='tt0343660', "igdb_id"=NULL, "title"='50 First Dates', "original_title"='50 First Dates', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/lzUI2Cg7OMfcUNv3f7MywYNBjs6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/v8lPo8UWKyP2tIXD8N64HfNP4Pw.jpg', "overview"='Henry is a player skilled at seducing women. But when this veterinarian meets Lucy, a girl with a quirky problem when it comes to total recall, he realizes it''s possible to fall in love all over again…and again, and again. That''s because the delightful Lucy has no short-term memory, so Henry must woo her day after day until he finally sweeps her off her feet.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.0551, "vote_average"=6.874, "is_ambiguous"=0, "evidence_score"=1.46958333333333328e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-20 01:43:50' WHERE "id"=3467;
UPDATE "recommendations" SET "tmdb_id"=2770, "imdb_id"='tt0252866', "igdb_id"=NULL, "title"='American Pie 2', "original_title"='American Pie 2', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/854ZZxXdeabAs90mrV72NqShJqR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/as3gvp4DIXVRlXsj5x7OWPQI5lI.jpg', "overview"='After a year apart - attending different schools, meeting different people - the guys rent a beach house and vow to make this the best summer ever. As it turns out, whether that will happen or not has a lot to do with the girls. Between the wild parties, outrageous revelations and yes, a trip to band camp, they discover that times change and people change, but in the end, it''s all about sticking together.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.8215, "vote_average"=6.263, "is_ambiguous"=0, "evidence_score"=1.17888888888888878e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-20 01:43:50' WHERE "id"=3478;
