UPDATE "recommendations" SET "tmdb_id"=16871, "imdb_id"='tt1127180', "igdb_id"=NULL, "title"='Drag Me to Hell', "original_title"='Drag Me to Hell', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/fdyejM5Zd6dsa0YyWa02ZAKwQzK.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3tvwsRSIDgwJuaGdh67XZ942UMy.jpg', "overview"='After denying a woman the extension she needs to keep her home, loan officer Christine Brown sees her once-promising life take a startling turn for the worse. Christine is convinced she''s been cursed by a Gypsy, but her boyfriend is skeptical. Her only hope seems to lie in a psychic who claims he can help her lift the curse and keep her soul from being dragged straight to hell.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.8749, "vote_average"=6.489, "is_ambiguous"=0, "evidence_score"=1.33299999999999982e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-20 01:43:50' WHERE "id"=4012;
