UPDATE "recommendations" SET "tmdb_id"=11557, "imdb_id"='tt0090060', "igdb_id"=NULL, "title"='St. Elmo''s Fire', "original_title"='St. Elmo''s Fire', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/g2SL3XHJas7hebZ2hhTrYLpKToD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uhAzDn1U51rANMuxQGxxqLORFZs.jpg', "overview"='Reluctant to let go of college life, a close-knit team of seven friends--irresponsible saxophone player Billy, young Republican Alec, his girlfriend Leslie, struggling journalist Kevin, drama queen Jules, lovesick waiter Kirby, and Wendy, a social worker with a heart of gold--realise the party is over. And as the burdens of maturity close in on the young dreamers, the complexities of adulthood and the daily struggle of growing up put their sacred friendship to the test. But everyone knows life is not a bed of roses. It won''t be easy, but when all is said and done, what will it take for St. Elmo''s clique to find its place in the real world?', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6921, "vote_average"=6.13, "is_ambiguous"=0, "evidence_score"=12.53, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-20 01:43:50' WHERE "id"=4028;
