UPDATE "recommendations" SET "tmdb_id"=11455, "imdb_id"='tt0078446', "igdb_id"=NULL, "title"='Up in Smoke', "original_title"='Up in Smoke', "media_type"='movie', "release_year"=1978, "poster_url"='https://image.tmdb.org/t/p/w500/bZclIeyzmybXLe3hTbFOIqlyPE0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fDidG4lYDDnG5gPQIFHBbixWRGS.jpg', "overview"='An unemployed pot-smoking slacker and amateur drummer, Anthony Stoner ditches his strict parents and hits the road, eventually meeting kindred spirit Pedro de Pacas. While the drug-ingesting duo is soon arrested for possession of marijuana, Anthony and Pedro get released on a technicality, allowing them to continue their many misadventures and ultimately compete in a rock band contest, where they perform the raucous tune "Earache My Eye."', "external_url"=NULL, "platforms"=NULL, "popularity"=2.4753, "vote_average"=6.617, "is_ambiguous"=0, "evidence_score"=1.26266666666666651e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-20 01:43:50' WHERE "id"=4155;
