UPDATE "recommendations" SET "tmdb_id"=5895, "imdb_id"='tt0279077', "igdb_id"=NULL, "title"='FLCL', "original_title"='フリクリ', "media_type"='tv', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/FkgA8CcmiLJGVCRYRQ2g2UfVtF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uiBb01nmHwyVTSILSMKJ4WIvijc.jpg', "overview"='Naota is a normal boy who kills some time with a normal girl by a stream that flows underneath a bridge. Nothing unusual happens in this town. The fact that Haruhara Haruko crashes into the main character with her Vespa a short while later and subsequently hits him over the head with her Rickenbacker 4003 bass guitar doesn’t really make any difference to any other day here. The at first glance unconnected, bizarre events that don’t seem to follow any pattern whatsoever don’t change anything about Naota’s boring life, either – because nothing incredible ever happens in this town.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.4617, "vote_average"=7.916, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-20 01:43:50' WHERE "id"=5618;
