UPDATE "recommendations" SET "tmdb_id"=71915, "imdb_id"='tt1869454', "igdb_id"=NULL, "title"='Good Omens', "original_title"='Good Omens', "media_type"='tv', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/nO68XVx5of8hlBwEOGOkPC8Mveu.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dQCKc5NKeKOGAQusk2FdctGB9k5.jpg', "overview"='Aziraphale and Crowley, of Heaven and Hell respectively, have grown rather fond of the Earth. So it''s terrible news that it''s about to end. The armies of Good and Evil are amassing. The Four Horsemen are ready to ride. Everything is going according to the Divine Plan...except that someone seems to have misplaced the Antichrist. Can our heroes find him and stop Armageddon before it''s too late?', "external_url"=NULL, "platforms"=NULL, "popularity"=25.3285, "vote_average"=8.026, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-20 01:43:50' WHERE "id"=5676;
UPDATE "recommendations" SET "tmdb_id"=43236, "imdb_id"='tt0050839', "igdb_id"=NULL, "title"='Peyton Place', "original_title"='Peyton Place', "media_type"='movie', "release_year"=1957, "poster_url"='https://image.tmdb.org/t/p/w500/pSANpoBLMbejWTtiKz630eSaDpi.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rjji4uYr1Uu6VAsZasIrRVQqzUC.jpg', "overview"='In the outwardly respectable New England community of Peyton Place, shopkeeper Constance McKenzie tries to make up for a past indiscretion -- which resulted in her illegitimate daughter Allison  -- by adopting a chaste, prudish attitude towards all things sexual.  In spite of herself, Constance can''t help but be attracted to handsome new teacher Michael Rossi. Meanwhile, the restless Allison, who''d like to be as footloose and fancy-free as the town''s "fast girl" Betty Anderson, falls sincerely in love with mixed-up mama''s boy Norman Page.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.58, "vote_average"=6.763, "is_ambiguous"=0, "evidence_score"=5.2625, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-20 01:43:50' WHERE "id"=5691;
