UPDATE "recommendations" SET "tmdb_id"=1885, "imdb_id"='tt0087538', "igdb_id"=NULL, "title"='The Karate Kid', "original_title"='The Karate Kid', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/1mp4ViklKvA0WXXsNvNx0RBuiit.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/j1xaeJZOEOiVBD1rk3dg4YaAk23.jpg', "overview"='New Jersey teen Daniel LaRusso moves to Los Angeles with his mother, and soon strikes up a relationship with Ali. He quickly finds himself the target of bullying by a group of thugs, led by Ali''s ex-boyfriend Johnny, who study karate at the Cobra Kai dojo under ruthless sensei John Kreese. Fortunately, Daniel befriends Mr. Miyagi, an unassuming repairman who just happens to be a martial arts master himself. Miyagi takes Daniel under his wing, training him in a more compassionate form of karate for self-defense and, later, preparing him to compete against the brutal Cobra Kai.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.5942, "vote_average"=7.228, "is_ambiguous"=0, "evidence_score"=12.96, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-20 01:43:50' WHERE "id"=5728;
