UPDATE "recommendations" SET "tmdb_id"=26477, "imdb_id"='tt0092608', "igdb_id"=NULL, "title"='Back to the Beach', "original_title"='Back to the Beach', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/geA6raOQ8rnEkX31r6a8mteJCW8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kUiFHTcetvLIX9FxYjC5ppRn1lB.jpg', "overview"='Cowabunga! The surfing ''60s ride into the new wave as Frankie and Annette star in this hip update of their old-time, good-time beach movies. With special appearances by Bob Denver, Tony Dow, Pee-Wee Herman, Jerry Mathers and other familiar faces. Frankie and Annette grow up and have kids in the midwest. They return to LA to visit their daughter who is shacked up with her boyfriend and tries to hide the fact. They begin to have marriage problems when Frankie runs into Connie, who has erected a shrine to him in her night club. Their punk son has joined up with the local surf toughs, and things all come to a head when the toughs challenge the good guys to a surfing duel', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9022, "vote_average"=5.896, "is_ambiguous"=0, "evidence_score"=5.52666666666666728e+00, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-20 01:43:50' WHERE "id"=5820;
UPDATE "recommendations" SET "tmdb_id"=23514, "imdb_id"='tt0376136', "igdb_id"=NULL, "title"='The Rum Diary', "original_title"='The Rum Diary', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/uErFROiMrpk7owQWKK3bpD4hSJs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jxsWn2D4pk0rgtO3hBzFq9rROZ8.jpg', "overview"='Tired of the noise and madness of New York and the crushing conventions of late Eisenhower-era America, itinerant journalist Paul Kemp travels to the pristine island of Puerto Rico to write for a local San Juan newspaper run by the downtrodden editor Lotterman. Adopting the rum-soaked lifestyle of the late ‘50s version of Hemingway’s ''The Lost Generation'', Paul soon becomes entangled with a very attractive American woman and her fiancée, a businessman involved in shady property development deals.  It is within this world that Kemp ultimately discovers his true voice as a writer and integrity as a man.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5636, "vote_average"=5.882, "is_ambiguous"=0, "evidence_score"=5.5125, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-20 01:43:50' WHERE "id"=5825;
