UPDATE "recommendations" SET "tmdb_id"=232564, "imdb_id"='tt1824247', "igdb_id"=NULL, "title"='Tommy', "original_title"='Tommy', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/A9pp1FRdynQ7rM9WxzaFyb4XGdy.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hX8qH6cRQp2VGaxwRMgNK1g4Oqt.jpg', "overview"='Tommy Seebach Mortensen; or just Tommy Seebach to the whole nation; were born in Copenhagen in 1949 and passed away far too early in 2003.  "Tommy" received four stars out of six by Politiken,[6] Berlingske Tidende[7] and Ekstra Bladet;[8] B.T. awarded it six stars out of six.[9] Dagbladet Information described it as "... a story of an artist who became a victim of the musical genre which he himself had helped innovate, and who, instead of gaining the broad recognition he had longed for his entire life, ended up with a status somewhere in between national heritage and kitsch clown..."[10] Politiken called the film "worthy, worth seeing and moving", Ekstra Bladet "a moving portrait of a man caught between the music, his family and the bottle".', "external_url"=NULL, "platforms"=NULL, "popularity"=1.5867, "vote_average"=8.3, "is_ambiguous"=0, "evidence_score"=2.07, "created_at"='2026-08-05 03:13:48', "updated_at"='2026-08-20 01:43:50' WHERE "id"=7460;
