UPDATE "recommendations" SET "tmdb_id"=294682, "imdb_id"='tt3474600', "igdb_id"=NULL, "title"='Little Forest: Summer/Autumn', "original_title"='リトル・フォレスト 夏・秋', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/qDcoxRjv1bH29Hy8iTyOW1UnW9y.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1bAE9YexmEfAanXKaO1d9Ms4qKm.jpg', "overview"='Fleeing heartbreak in the big city, Ichiko returns to Komori, her rural hometown. She battles summer''s rain and humidity, bakes her own bread, grows hothouse tomatoes and tills the fields. During autumn, the time for pickling and preserving fish and sweet potatoes, Ichiko begins reaping rice and recalls her departure five years before.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.1052, "vote_average"=7.77, "is_ambiguous"=0, "evidence_score"=9.77, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-20 01:43:50' WHERE "id"=10211;
UPDATE "recommendations" SET "tmdb_id"=364540, "imdb_id"='tt3955894', "igdb_id"=NULL, "title"='Girl Asleep', "original_title"='Girl Asleep', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/yHmXk0j8RTKV9br3wEKCm9ApZag.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3VD3BseZJvAMagjTY9oH1bbQR8R.jpg', "overview"='The world is closing in on Greta Driscoll. On the cusp of turning fifteen, she can’t bear to leave her childhood; it contains all the things that give her comfort in an incomprehensible new world. She floats in a bubble of loserdom with her only friend, Elliott, until her parents throw her a surprise fifteenth birthday party and she’s flung into a parallel place—a world that’s weirdly erotic, a little bit violent, and thoroughly ludicrous. Only there can she find herself.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8273, "vote_average"=6.076, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-20 01:43:50' WHERE "id"=10350;
